/**
 * Lengkapi setiap produk dengan `brand` (dari data brands) dan `slug` unik.
 * Slug dibuat dari nama produk; bila ada nama kembar, model dipakai sebagai pembeda.
 */
function withDerivedFields(seeds: ProductSeed[]): Product[] {
  const used = new Set<string>();

  return seeds.map((seed) => {
    const base = slugify(seed.name) || seed.id;
    let slug = base;

    if (used.has(slug)) {
      slug = slugify(`${seed.name} ${seed.model}`) || seed.id;
    }
    let suffix = 2;
    while (used.has(slug)) {
      slug = `${base}-${suffix}`;
      suffix += 1;
    }
    used.add(slug);

    return { ...seed, brand: brandName(seed.brandId), slug };
  });
}

export const products: Product[] = withDerivedFields(productSeeds);

/* ==========================================================================
   OPSI FILTER (FACET)
   Semuanya dihitung dari data produk, bukan daftar manual. Konsekuensinya:
   filter tidak pernah menampilkan pilihan yang nol produk, dan menambah
   produk baru otomatis menambah opsi filternya.
   ========================================================================== */

/** Brand yang benar-benar punya produk. */
export const productBrands = brands.filter((brand) =>
  products.some((product) => product.brandId === brand.id),
);

/** Subkategori yang dipakai minimal satu produk, urut sesuai taksonomi. */
export const productSubcategories = allSubcategories.filter((subcategory) =>
  products.some((product) => product.subcategory === subcategory),
);

/** Urutkan teks mengikuti aturan alfabet Indonesia. */
const sortID = (values: string[]) => [...values].sort((a, b) => a.localeCompare(b, "id"));

/** Jenis produk unik dari seluruh katalog. */
export const productTypes = sortID([
  ...new Set(products.map((product) => product.productType)),
]);

/** Bidang penggunaan unik dari seluruh katalog. */
export const productApplications = sortID([
  ...new Set(products.flatMap((product) => product.applications ?? [])),
]);

/** Status ketersediaan yang benar-benar dipakai. */
export const productAvailabilities = availabilityOptions.filter((option) =>
  products.some((product) => product.availability === option),
);

/** Subkategori milik satu kategori saja - dipakai agar filter saling menyesuaikan. */
export function subcategoriesInCategories(categories: string[]) {
  if (categories.length === 0) return productSubcategories;
  return productSubcategories.filter((subcategory) =>
    products.some(
      (product) =>
        product.subcategory === subcategory && categories.includes(product.category),
    ),
  );
}

/* ==========================================================================
   URUTAN KATALOG
   ========================================================================== */

/**
 * Pengacak angka yang dapat diulang (mulberry32).
 * "Seeded" artinya: seed yang sama SELALU menghasilkan urutan yang sama.
 * Inilah yang membuat katalog terlihat acak, tetapi tidak berpindah-pindah
 * saat pengguna memfilter, mencari, atau menekan "Tampilkan lebih banyak".
 */
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a += 0x6d2b79f5;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Urutan katalog: acak, TETAPI tiga produk teratas selalu mewakili tiga
 * kategori utama secara berurutan - Reagen, Alat Lab, lalu Alat Kesehatan.
 *
 * Wakil tiap kategori diambil dari produk `featured: true` lebih dahulu; bila
 * tidak ada yang ditandai, produk mana pun dari kategori itu dipakai. Jadi
 * Anda bisa mengatur "produk andalan" hanya dengan satu field di data.
 */
export function orderedCatalog(seed: number, source: Product[] = products): Product[] {
  const shuffled = [...source];
  const random = mulberry32(seed);

  // Fisher-Yates: distribusi acak yang merata
  for (let i = shuffled.length - 1; i > 0; i -= 1) {
    const j = Math.floor(random() * (i + 1));
    const a = shuffled[i] as Product;
    const b = shuffled[j] as Product;
    shuffled[i] = b;
    shuffled[j] = a;
  }

  const lead: Product[] = [];
  productCategories.forEach((category) => {
    const inCategory = shuffled.filter((product) => product.category === category);
    const pick = inCategory.find((product) => product.featured) ?? inCategory[0];
    if (pick) lead.push(pick);
  });

  const leadIds = new Set(lead.map((product) => product.id));
  return [...lead, ...shuffled.filter((product) => !leadIds.has(product.id))];
}

/** Cari produk dari slug URL. Dipakai route dinamis /artha-labs/[slug]. */
export function getProductBySlug(slug: string) {
  return products.find((product) => product.slug === slug);
}

/** Semua slug produk - dipakai generateStaticParams & sitemap. */
export const productSlugs = products.map((product) => product.slug);

/**
 * Produk terkait: prioritas daftar manual (`relatedProductIds`), lalu subkategori
 * sama, lalu kategori sama, lalu brand sama. Produk yang sedang dibuka tidak
 * pernah ikut tampil.
 */
export function getRelatedProducts(product: Product, limit = 3): Product[] {
  const pool = products.filter((item) => item.id !== product.id);
  const picked: Product[] = [];

  const push = (candidate?: Product) => {
    if (candidate && !picked.some((item) => item.id === candidate.id)) {
      picked.push(candidate);
    }
  };

  product.relatedProductIds?.forEach((id) => push(pool.find((item) => item.id === id)));
  pool.filter((item) => item.subcategory === product.subcategory).forEach(push);
  pool.filter((item) => item.category === product.category).forEach(push);
  pool.filter((item) => item.brandId === product.brandId).forEach(push);

  return picked.slice(0, limit);
}